import { StrictMode } from "react";
import { createRoot } from "react-dom/client";

import { ComponentContext, getStudioProApi, IComponent, StudioProApi } from "@mendix/extensions-api";

import { Agent } from "../../types/agent";

import AppThemeProvider from "../components/AppThemeProvider";

import { createStudioProLogger } from "../../config/logger";

import ModelSettingsEditor from "./modelSettingsEditor";

interface AppProps {
    studioPro: StudioProApi;
    agent: Agent;
    onClose: (result: Agent | null) => void;
}
const App: React.FC<AppProps> = ({ studioPro, agent, onClose }) => {
    return (
        <AppThemeProvider studioPro={studioPro}>
            <ModelSettingsEditor initialAgent={agent} onClose={onClose} />
        </AppThemeProvider>
    );
};

export const component: IComponent = {
    async loaded(componentContext: ComponentContext, componentInput: { dialogId: string; agent: string }) {
        const studioPro = getStudioProApi(componentContext);
        const logger = createStudioProLogger(studioPro);

        if (!componentInput.agent) {
            throw new Error("Agent needs to be provided to open the Model Settings dialog.");
        }

        try {
            const agent: Agent = JSON.parse(decodeURIComponent(componentInput.agent));

            const rootElement = document.getElementById("root");
            if (!rootElement) {
                throw new Error("Failed to find the root element.");
            }

            const root = createRoot(rootElement);

            const handleClose = (result: Agent | null) => {
                // Set the result on the component context before closing
                studioPro.ui.dialogs.closeWithResult(componentInput.dialogId, result);
            };

            root.render(
                <StrictMode>
                    <App studioPro={studioPro} agent={agent} onClose={handleClose} />
                </StrictMode>
            );
        } catch (error) {
            logger.error("Error editing model settings:", error);
            throw new Error("Error editing model settings:", error as Error);
        }
    },
};
